import fs from 'node:fs';

/**
 * PHPInfoParser
 * -------------
 * Exhaustively parses the HTML output of the PHP phpinfo() function with no
 * external dependency (no npm library required, only the native "fs" module
 * for the optional file read).
 *
 * Usage:
 *   const parser = new PHPInfoParser(html);
 *   const obj  = parser.toObject();
 *   const md   = parser.toMarkdown();
 *
 *   // or straight from a file:
 *   const parser2 = PHPInfoParser.fromFile('./phpinfo.html');
 */
class PHPInfoParser {
	/**
	 * @param {string} html The full HTML generated by phpinfo()
	 */
	constructor(html) {
		if (typeof html !== 'string' || !html.trim()) {
			throw new TypeError('PHPInfoParser: the provided HTML is empty or invalid.');
		}
		this.html = html;
		this._parsed = null; // cache
	}

	/** Instantiates the parser straight from a file on disk. */
	static fromFile(path, encoding = 'utf8') {
		const html = fs.readFileSync(path, encoding);
		return new PHPInfoParser(html);
	}

	/**
	 * Instantiates the parser from an HTML string already in memory (e.g.
	 * fetched via fetch(), an HTTP request, a converted buffer, etc.).
	 * Strictly equivalent to `new PHPInfoParser(html)`, provided for symmetry
	 * with `fromFile()`.
	 */
	static fromString(html) {
		return new PHPInfoParser(html);
	}

	// ------------------------------------------------------------------
	// Low-level helpers: HTML decoding / tag extraction
	// ------------------------------------------------------------------

	/** Decodes the most common HTML entities. */
	static decodeEntities(str) {
		if (!str) return '';
		return str
			.replace(/&nbsp;/gi, ' ')
			.replace(/&amp;/gi, '&')
			.replace(/&lt;/gi, '<')
			.replace(/&gt;/gi, '>')
			.replace(/&quot;/gi, '"')
			.replace(/&#0?39;/gi, "'")
			.replace(/&apos;/gi, "'")
			.replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
			.replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(parseInt(dec, 10)));
	}

	/**
	 * Strips every HTML tag from a fragment and returns the clean text.
	 * <br> is converted to a newline, <i>no value</i> is normalized to null
	 * upstream (see extractCells), the rest is simply removed.
	 */
	static stripTags(fragment) {
		if (!fragment) return '';
		const withBreaks = fragment
			.replace(/<br\s*\/?>/gi, '\n')
			.replace(/<\/(p|div|li)>/gi, '\n')
			.replace(/<[^>]+>/g, '');
		return PHPInfoParser.decodeEntities(withBreaks)
			.replace(/[ \t]+/g, ' ')
			.replace(/\n\s+/g, '\n')
			.replace(/\s+\n/g, '\n')
			.trim();
	}

	/** Extracts an attribute value (e.g. class="e") from a tag's opening attributes string. */
	static getAttr(tagOpenAttrs, name) {
		const m = new RegExp(name + '\\s*=\\s*"([^"]*)"', 'i').exec(tagOpenAttrs);
		return m ? m[1] : null;
	}

	// ------------------------------------------------------------------
	// Step 1: split the document into top-level blocks
	//         (h1, h2, table) in order of appearance
	// ------------------------------------------------------------------

	static extractTopLevelBlocks(html) {
		const blockRe = /<h1[^>]*>[\s\S]*?<\/h1>|<h2[^>]*>[\s\S]*?<\/h2>|<table[^>]*>[\s\S]*?<\/table>/gi;
		const blocks = [];
		let m;
		while ((m = blockRe.exec(html)) !== null) {
			const raw = m[0];
			let type;
			if (/^<h1/i.test(raw)) type = 'h1';
			else if (/^<h2/i.test(raw)) type = 'h2';
			else type = 'table';
			blocks.push({ type, raw });
		}
		return blocks;
	}

	// ------------------------------------------------------------------
	// Step 2: extract the rows (tr) and cells (td/th) of a table
	// ------------------------------------------------------------------

	static extractRows(tableHtml) {
		const rowRe = /<tr([^>]*)>([\s\S]*?)<\/tr>/gi;
		const rows = [];
		let m;
		while ((m = rowRe.exec(tableHtml)) !== null) {
			const trAttrs = m[1];
			const trClass = PHPInfoParser.getAttr(trAttrs, 'class') || '';
			rows.push({
				isHeader: /\bh\b/.test(trClass),
				cssClass: trClass,
				cells: PHPInfoParser.extractCells(m[2]),
			});
		}
		return rows;
	}

	static extractCells(rowHtml) {
		const cellRe = /<(t[hd])([^>]*)>([\s\S]*?)<\/t[hd]>/gi;
		const cells = [];
		let m;
		while ((m = cellRe.exec(rowHtml)) !== null) {
			const tag = m[1].toLowerCase();
			const attrs = m[2];
			const inner = m[3];
			const cls = PHPInfoParser.getAttr(attrs, 'class');
			const colspan = PHPInfoParser.getAttr(attrs, 'colspan');
			let text = PHPInfoParser.stripTags(inner);
			// phpinfo prints <i>no value</i> for an empty value → normalize it
			if (/^<i>\s*no value\s*<\/i>$/i.test(inner.trim())) text = null;
			cells.push({ tag, cls, colspan: colspan ? parseInt(colspan, 10) : 1, text });
		}
		return cells;
	}

	static parseTable(tableHtml) {
		const rows = PHPInfoParser.extractRows(tableHtml);
		const headerRows = rows.filter((r) => r.isHeader);
		const dataRows = rows.filter((r) => !r.isHeader);
		return { headerRows, dataRows };
	}

	// ------------------------------------------------------------------
	// Step 3: "high level" interpretation of a table to build an
	//         ergonomic object (caption / columns / rows / note)
	// ------------------------------------------------------------------

	static interpretTable(rawTable) {
		const { headerRows, dataRows } = rawTable;

		const result = {
			caption: null,   // table title, e.g. "PHP Group", "Features"
			columns: null,   // column headers, e.g. ["Directive","Local Value","Master Value"]
			entries: null,   // interpreted data (see below)
			note: null,       // table made only of text (no data)
			raw: rawTable,    // kept whole for exhaustive access
		};

		// No header row → "raw" data table (the most common case)
		if (headerRows.length === 0) {
			result.entries = PHPInfoParser._rowsToEntries(dataRows);
			return result;
		}

		// One or two header rows. We separate a possible "caption" (a
		// single-cell header row, often with colspan) from the real column
		// headers (a row with 2 cells or more).
		let captionRow = null;
		let columnRow = null;
		for (const hr of headerRows) {
			if (hr.cells.length <= 1) {
				if (!captionRow) captionRow = hr;
			} else if (!columnRow) {
				columnRow = hr;
			}
		}

		if (captionRow) {
			result.caption = captionRow.cells.map((c) => c.text).join(' ').trim() || null;
		}
		if (columnRow) {
			result.columns = columnRow.cells.map((c) => c.text);
		}

		// Header row(s) only, no data → a plain block of text (note)
		if (dataRows.length === 0) {
			result.note = result.caption || (result.columns ? result.columns.join(' | ') : null);
			return result;
		}

		if (result.columns) {
			// Table with named columns (e.g. php.ini directives, credits tables)
			result.entries = dataRows.map((row) => {
				const obj = {};
				row.cells.forEach((cell, i) => {
					const key = result.columns[i] !== undefined ? result.columns[i] : `col${i}`;
					obj[key] = cell.text;
				});
				return obj;
			});
		} else {
			// Simple key/value table (or list), possibly under a caption
			result.entries = PHPInfoParser._rowsToEntries(dataRows);
		}

		return result;
	}

	/** Turns raw data rows into an ordered list of {label, value}. */
	static _rowsToEntries(dataRows) {
		return dataRows.map((row) => {
			const texts = row.cells.map((c) => c.text);
			if (texts.length === 1) {
				return { label: texts[0], value: null };
			}
			if (texts.length === 2) {
				return { label: texts[0], value: texts[1] };
			}
			// More than 2 columns with no named header (rare) → keep everything.
			return { label: texts[0], value: texts.slice(1) };
		});
	}

	// ------------------------------------------------------------------
	// Step 4: split into sections (General + one h2 per module) and
	//         build the final object
	// ------------------------------------------------------------------

	parse() {
		if (this._parsed) return this._parsed;

		const html = this.html;

		// Title / version
		const titleMatch = /<title>([\s\S]*?)<\/title>/i.exec(html);
		const title = titleMatch ? PHPInfoParser.stripTags(titleMatch[1]) : null;
		const versionMatch = title && /PHP\s+([\d.]+(?:-\S+)?)/i.exec(title);
		const version = versionMatch ? versionMatch[1] : null;

		const blocks = PHPInfoParser.extractTopLevelBlocks(html);

		const sections = [];
		let current = { name: 'General', tables: [] };
		sections.push(current);

		for (const block of blocks) {
			if (block.type === 'h1' || block.type === 'h2') {
				const name = PHPInfoParser.stripTags(block.raw.replace(/^<h[12][^>]*>|<\/h[12]>$/gi, ''));
				if (!name) continue; // empty header, ignored
				current = { name, tables: [] };
				sections.push(current);
			} else if (block.type === 'table') {
				const raw = PHPInfoParser.parseTable(block.raw);
				const interpreted = PHPInfoParser.interpretTable(raw);
				current.tables.push(interpreted);
			}
		}

		// Drop purely decorative sections (titles with no table at all, e.g.
		// the <h1>Configuration</h1> that only introduces the modules).
		const cleanedSections = sections.filter((s) => s.tables.length > 0);

		this._parsed = { title, version, sections: cleanedSections };
		return this._parsed;
	}

	// ------------------------------------------------------------------
	// Public API
	// ------------------------------------------------------------------

	/** Returns the full structure as a JavaScript object. */
	toObject() {
		return this.parse();
	}

	/**
	 * Returns a flattened "index" structure (section → key → value), meant for
	 * looking a value up quickly, not for rebuilding the HTML. Unlike
	 * toObject(), tables are reduced to plain key/value pairs: no more nested
	 * columns/entries/raw.
	 *
	 * - Simple key/value table (e.g. "PHP Version" → "8.2.1")
	 * - Column table (e.g. php.ini directives) → one object per row, with
	 *   automatic simplification when a single column remains after the key
	 *   (e.g. { allow_url_fopen: { local: "On", master: "On" } })
	 * - "note" table (text only, no data) → string directly
	 * - A "caption" (table legend) creates a sub-object in the section to
	 *   avoid key collisions between neighboring tables.
	 */
	toKeyValue() {
		const { title, version, sections } = this.parse();
		const out = { title, version, sections: {} };

		for (const section of sections) {
			const sectionObj = {};

			for (const table of section.tables) {
				const target = table.caption
					? (sectionObj[table.caption] ??= {})
					: sectionObj;

				if (table.note) {
					if (table.caption) sectionObj[table.caption] = table.note;
					else sectionObj.note = table.note;
					continue;
				}

				if (table.columns) {
					const [keyCol, ...restCols] = table.columns;
					for (const entry of table.entries ?? []) {
						const key = entry[keyCol];
						if (key === null || key === undefined || key === '') continue;
						if (restCols.length === 1) {
							target[key] = entry[restCols[0]] ?? null;
						} else {
							const rest = {};
							for (const col of restCols) rest[col] = entry[col] ?? null;
							target[key] = rest;
						}
					}
				} else if (Array.isArray(table.entries)) {
					for (const entry of table.entries) {
						if (entry.label === null || entry.label === undefined) continue;
						target[entry.label] = entry.value;
					}
				}
			}

			out.sections[section.name] = sectionObj;
		}

		return out;
	}

	/** Shortcut to get a section (module) by name (case-insensitive). */
	getSection(name) {
		const { sections } = this.parse();
		const needle = name.toLowerCase();
		return sections.find((s) => s.name.toLowerCase() === needle) || null;
	}

	/** Lists the names of every detected section/module. */
	listSections() {
		return this.parse().sections.map((s) => s.name);
	}

	/**
	 * Looks up a php.ini directive by its exact name across every section.
	 * Returns { section, local, master } or null.
	 */
	findDirective(directiveName) {
		const { sections } = this.parse();
		for (const section of sections) {
			for (const table of section.tables) {
				if (!table.columns || !Array.isArray(table.entries)) continue;
				const directiveKey = table.columns.find((c) => /directive/i.test(c));
				if (!directiveKey) continue;
				const found = table.entries.find((e) => e[directiveKey] === directiveName);
				if (found) {
					return {
						section: section.name,
						directive: found[directiveKey],
						local: found['Local Value'] !== undefined ? found['Local Value'] : null,
						master: found['Master Value'] !== undefined ? found['Master Value'] : null,
					};
				}
			}
		}
		return null;
	}

	/** Generates an exhaustive, readable Markdown rendering of the parsed phpinfo(). */
	toMarkdown() {
		const { title, version, sections } = this.parse();
		const lines = [];

		lines.push(`# ${title || 'phpinfo()'}`);
		if (version) lines.push(`\n**PHP version:** ${version}`);
		lines.push('');

		for (const section of sections) {
			lines.push(`## ${section.name}`);
			lines.push('');

			for (const table of section.tables) {
				if (table.caption) {
					lines.push(`**${table.caption}**`);
					lines.push('');
				}

				if (table.note) {
					lines.push(`> ${table.note}`);
					lines.push('');
					continue;
				}

				if (table.columns) {
					// Table with named columns (php.ini directives, credits tables...)
					lines.push(`| ${table.columns.join(' | ')} |`);
					lines.push(`| ${table.columns.map(() => '---').join(' | ')} |`);
					for (const entry of table.entries) {
						const row = table.columns.map((c) => {
							const v = entry[c];
							return v === null || v === undefined ? '_no value_' : String(v).replace(/\n/g, '<br>').replace(/\|/g, '\\|');
						});
						lines.push(`| ${row.join(' | ')} |`);
					}
					lines.push('');
				} else if (Array.isArray(table.entries)) {
					// Table with no named headers (key/value): still render it as a
					// 2-column Markdown table, not a list.
					lines.push('| Key | Value |');
					lines.push('| --- | --- |');
					for (const entry of table.entries) {
						const label = String(entry.label).replace(/\n/g, '<br>').replace(/\|/g, '\\|');
						let val;
						if (entry.value === null || entry.value === undefined) val = '_no value_';
						else if (Array.isArray(entry.value)) val = entry.value.join(', ');
						else val = String(entry.value).replace(/\n/g, '<br>');
						val = String(val).replace(/\|/g, '\\|');
						lines.push(`| ${label} | ${val} |`);
					}
					lines.push('');
				}
			}
		}

		return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim() + '\n';
	}
}

export default PHPInfoParser;
